mapper.select:
SELECT ar.*, u1.username as applicant_username, u1.role as applicant_role_user, u2.username as reviewer_username, s.schedule_date, s.time_slot, d.name as doctor_name, d.title as doctor_title FROM application_request ar LEFT JOIN user u1 ON ar.applicant_id = u1.id LEFT JOIN user u2 ON ar.reviewer_id = u2.id LEFT JOIN schedule s ON ar.schedule_id = s.id LEFT JOIN doctor d ON ar.doctor_id = d.id
AND ar.request_type = #{requestType}
AND ar.status = #{status}
AND ar.applicant_id = #{applicantId}
AND ar.doctor_id = #{doctorId}
ORDER BY ar.created_at DESC

