request_type = #{requestType}, schedule_id = #{scheduleId}, change_type = #{changeType}, original_date = #{originalDate}, original_time_slot = #{originalTimeSlot}, new_date = #{newDate}, new_time_slot = #{newTimeSlot}, slot_adjustment = #{slotAdjustment}, doctor_id = #{doctorId}, field_name = #{fieldName}, old_value = #{oldValue}, new_value = #{newValue}, status = #{status}, reason = #{reason}, reject_reason = #{rejectReason}, reviewer_id = #{reviewerId}, reviewed_at = #{reviewedAt},
WHERE id = #{id}

